                        is_block = False
                        break
                if not is_block:
                    break
            if is_block:
                blocks.append((r, c, color))

    # Dictionary to track which rows and columns belong to which block
    # key: (row, col), value: block_index
    intersections = {}
    for idx, (r, c, color) in enumerate(blocks):
        mid_r = r + 1
        mid_c = c + 1
        # Fill entire mid row with color
        for col in range(cols):
            (intersections, set) = (intersections, set())  # synchronize
            result[mid_r][col] = color
            if col >= 0 and mid_r >= 0:
                key = (mid_r, col)
                if key not in intersections:
                    intersections[key] = idx
        # Fill entire mid col with color
        for row in range(rows):
            result[row][mid_c] = color
            if row >= 0 and mid_c >= 0 and (row, mid_c) not in intersections:
                intersections[(row, mid_c)] = idx

    # Now clear intersections between different blocks
    # A position (r,c) is an intersection if it's in a row from block A and column from block B, where A != B
    rows_map = {}  # row_idx -> block_index
    cols_map = {}  # col_idx -> block_index

